python3 << 'EOF'
import csv

files = {
    "97": "/workspace/res_1vs97.tsv",
    "98": "/workspace/res_1vs98.tsv", 
    "99": "/workspace/res_1vs99.tsv",
}

for strain, fpath in files.items():
    up_genes = []
    down_genes = []
    total = 0

    with open(fpath) as f:
        reader = csv.DictReader(f, delimiter='\t')
        for row in reader:
            total += 1
            gene = row['rowname']
            try:
                lfc = float(row['log2FoldChange'])
            except (ValueError, KeyError):
                continue
            if lfc > 1.5:
                up_genes.append(gene)
            elif lfc < -1.5:
                down_genes.append(gene)

    print(f"Strain {strain}: {total} genes total, {len(up_genes)} upregulated (lfc>1.5), {len(down_genes)} downregulated (lfc<-1.5)")

    # Write gene lists for upload
    with open(f"/workspace/up_97.txt", "w") as f:
        for g in up_genes:
            f.write(f"{g}\n")

    if strain == "97":
        with open(f"/workspace/up_97.txt", "w") as f:
            for g in up_genes:
                f.write(f"{g}\n")
        with open(f"/workspace/down_97.txt", "w") as f:
            for g in down_genes:
                f.write(f"{g}\n")
    elif strain == "98":
        with open(f"/workspace/up_98.txt", "w") as f:
            for g in up_genes:
                f.write(f"{g}\n")
        with open(f"/workspace/down_98.txt", "w") as f:
            for g in down_genes:
                f.write(f"{g}\n")
    elif strain == "99":
        with open(f"/workspace/up_99.txt", "w") as f:
            for g in up_genes:
                f.write(f"{g}\n")
        with open(f"/workspace/down_99.txt", "w") as f:
            for g in down_genes:
                f.write(f"{g}\n")

# Show first few genes from each
for prefix in ["up_97", "down_97"]:
    with open(f"/workspace/{prefix}.txt") as f:
        genes = [l.strip() for l in f.readlines()[:5]]
        print(f"{prefix}: {len(open(f'/workspace/{prefix}.txt').readlines())} genes, first: {genes}")
EOF

